const MAX_ABILITY_RANK = 5;
const DUPLICATE_CHANCE = .18;
const MAX_EQUIPPED_ECHOES = 3;
const MAX_EXPEDITION_LEVEL = 10;
const XP_REWARDS = {Normal:45,Elite:75,Boss:100};
