function abilityText(a){let dot=a.dot||3,dotTurns=a.dotTurns||3,weaken=a.weaken||4,bonus=a.bonus||6,power=a.power||3;if(a.type==='damage')return `Deal ${a.value} damage${a.execute?`. +${a.execute} below half health.`:'.'}`;if(a.type==='hybrid')return `Deal ${a.value} damage and heal the most wounded hero for ${a.heal}.`;if(a.type==='hex')return `Deal ${a.value} damage. Curse the target for ${a.hexTurns||2} actions: −${a.hexReduction||2} damage, then ${a.hexDamage||2} Hex damage after it acts.`;if(a.type==='weaken')return `Deal ${a.value} damage and reduce the next enemy attack by ${weaken}.`;if(a.type==='double')return `Deal ${a.value} damage with a 45% chance to strike twice.`;if(a.type==='poison')return `Deal ${a.value} damage and inflict ${dot} Poison for the next ${dotTurns} enemy actions. Reapplying refreshes it.`;if(a.type==='evade')return `Deal ${a.value} damage and evade the next enemy attack.${a.cooldown?' Cooldown: 1 hero turn.':''}`;if(a.type==='pact')return `Lose 3 health to deal ${a.value} damage.`;if(a.type==='heal')return `Heal every living hero for ${a.value}.`;if(a.type==='selfheal')return `Deal ${a.value} damage and restore ${a.heal} health to yourself.`;if(a.type==='expose')return `Deal ${a.value} damage; the next hero deals +${bonus}.`;if(a.type==='meteor')return `Deal ${a.value} damage, then this ability becomes exhausted.`;if(a.type==='cry')return `Deal ${a.value} damage and empower the next two attacks by ${power}.`;if(a.type==='chain')return `Deal ${a.value} damage to the target and ${a.chain||4} damage to another living enemy.`;if(a.type==='ward')return `Deal ${a.value} damage and gain ${a.ward||5} Ward against the next hit.`;if(a.type==='cleanse')return `Heal every living hero for ${a.value}, remove 1 Burn, and clear Chill.`;if(a.type==='interrupt')return `Deal ${a.value} damage. Replace the target's visible special intent with Strike. Exhausted after use.`;if(a.type==='intervention')return `Deal ${a.value} damage and heal the hero targeted by the visible intent for ${a.heal}.`;if(a.type==='shatter')return `Remove up to ${a.shatter||6} Armor or Veil from the target, then deal ${a.value} damage.`;if(a.type==='reap')return `Deal ${a.value} damage. If this defeats the target, heal every living hero for ${a.heal}.`;if(a.type==='sanctuary')return `Deal ${a.value} damage and reduce damage to every hero from the next enemy action by ${a.reduction||3}. Exhausted after use.`;if(a.type==='overflow')return `Deal ${a.value} damage. Excess damage carries into the next living enemy.`;return a.desc;}
function cooldownSlot(abilityName){return ABILITIES.find(a=>a.name===abilityName)?.type==='evade'?'full-evade':abilityName;}
function cooldownKey(heroId,abilityName){return `${heroId}::${cooldownSlot(abilityName)}`;}
function abilityCooldown(heroId,abilityName){return state.cooldowns?.[cooldownKey(heroId,abilityName)]||0;}
function setAbilityCooldown(heroId,abilityName,turns){if(turns>0)state.cooldowns[cooldownKey(heroId,abilityName)]=turns;}
function tickHeroCooldowns(heroId){Object.keys(state.cooldowns).forEach(key=>{if(!key.startsWith(`${heroId}::`))return;state.cooldowns[key]--;if(state.cooldowns[key]<=0)delete state.cooldowns[key];});}
function rankUpAbility(a){a.rank=Math.min(MAX_ABILITY_RANK,(a.rank||1)+1);let gain=a.type==='meteor'?3:['damage','pact','interrupt','reap','overflow'].includes(a.type)?2:1;if(typeof a.value==='number')a.value+=gain;if(a.heal)a.heal+=a.type==='reap'?1:2;if(a.type==='poison')a.dot=(a.dot||3)+1;if(a.type==='hex')a.hexDamage=(a.hexDamage||2)+1;if(a.type==='weaken')a.weaken=(a.weaken||4)+1;if(a.type==='expose')a.bonus=(a.bonus||6)+2;if(a.type==='cry')a.power=(a.power||3)+1;if(a.type==='chain')a.chain=(a.chain||4)+1;if(a.type==='ward')a.ward=(a.ward||5)+1;if(a.type==='shatter')a.shatter=(a.shatter||6)+1;if(a.type==='sanctuary')a.reduction=(a.reduction||3)+1;a.desc=abilityText(a);return a;}
function rankPreview(a){return rankUpAbility({...a});}
function xpToNext(level=state.expeditionLevel){return level>=MAX_EXPEDITION_LEVEL?0:80+20*(level-1);}
function expeditionDamageBonus(level=state.expeditionLevel){return DAMAGE_LEVELS.filter(milestone=>level>=milestone).length;}
function enemyHealthScale(level=state.expeditionLevel){return 1+.025*Math.max(0,level-1);}
function enemyDamageBonus(level=state.expeditionLevel){return level>=9?2:level>=5?1:0;}
function victoryXpReward(){let node=currentRouteNode();return node?.xp??(XP_REWARDS[state.encounterType]||XP_REWARDS.Normal);}
function grantVictoryXp(){
 let gain=victoryXpReward();state.lastXpGain=gain;state.lastLevelUps=[];
 if(state.expeditionLevel>=MAX_EXPEDITION_LEVEL){state.expeditionXp=0;return;}
 state.expeditionXp+=gain;
 while(state.expeditionLevel<MAX_EXPEDITION_LEVEL&&state.expeditionXp>=xpToNext()){
  state.expeditionXp-=xpToNext();state.expeditionLevel++;state.lastLevelUps.push(state.expeditionLevel);
  state.party.forEach(hero=>{hero.maxHp+=2;if(hero.currentHp>0)hero.currentHp+=2;});
 }
 if(state.expeditionLevel>=MAX_EXPEDITION_LEVEL)state.expeditionXp=0;
}

