function worldRoute(world=state.world){return WORLD_ROUTES.find(route=>route.world===world)||null;}
function routeNodeById(id,world=state.world){return worldRoute(world)?.nodes.find(node=>node.id===id)||null;}
function routeEncounterDefinition(node){return node?.routeEncounter?WORLD_ONE_ROUTE_ENCOUNTERS[node.routeEncounter]:Number.isInteger(node?.encounterIndex)?WORLDS[0].mobs[node.encounterIndex]:null;}
function encounterDefinition(world=state.world,level=state.level,node=currentRouteNode()){return world===0&&node?.routeEncounter?routeEncounterDefinition(node):WORLDS[world]?.mobs[level];}
function newRouteState(world=state.world){let route=worldRoute(world);return route?{version:1,world,path:[],activeNodeId:null,stage:'choosing',previewNodeId:route.startId}:null;}
function routeMode(){return state.world===0&&state.route?.world===0;}
function currentRouteNode(){return routeMode()?routeNodeById(state.route.activeNodeId):null;}
function availableRouteNodes(){if(!routeMode())return [];let route=worldRoute(),last=state.route.path[state.route.path.length-1],ids=last?routeNodeById(last)?.connections||[]:[route.startId];return ids.map(id=>routeNodeById(id)).filter(Boolean);}
function routeNodeAvailable(id){return availableRouteNodes().some(node=>node.id===id);}
function routeStep(){return routeMode()?Math.min(worldRoute().steps,state.route.path.length+(state.route.activeNodeId?1:0)+1):state.level+1;}
function routeProgressLabel(){let node=currentRouteNode();return routeMode()?`${node?routeRiskLabel(node):'Path'} · Step ${Math.min(worldRoute().steps,state.route.path.length+1)} of ${worldRoute().steps}`:`${state.encounterType} · Fight ${state.level+1} of 5`;}
