 if(world===0&&!saved.route&&saved.shopOpen){restored.route={version:1,world:0,path:['thorn-threshold','hunter-trail','wayfarer-cache','fungal-hollow','hunters-cache','mossbound-ogre'],activeNodeId:'wayfarer-reliquary',stage:'shop',previewNodeId:'wayfarer-reliquary'};restored.screen='map';}
 restored.animating=false;restored.fx=null;restored.sceneEntering=false;restored.encounterIntro=false;restored.encounterAssetsReady=true;restored.cardsArriving=false;
