 let attacker=state.enemies[attackerIndex],target=livingHeroes[Math.floor(Math.random()*livingHeroes.length)],kind='attack',basicNames={kindle:'Kindled Claw',creeperSnare:'Hooking Claw',trackerCull:'Gloam Claw',bloomHaze:'Rootbite',antlerWard:'Rooted Charge'},name=basicNames[attacker.pattern]||'Strike',icon='⚔️',damage=attacker.damage,burn=attacker.burn||0,healAmount=0,armorAmount=0,chill=0,clockAfter=attacker.clock||0,sealHeroId=null,sealAbilityName='',all=false,phase=0;
 if(attacker.pattern==='regrow'&&everyThird&&state.enemies.some(e=>e.hp>0&&e.hp<e.maxHp)){kind='regrow';name='Regrow';icon='🌿';damage=0;burn=0;healAmount=4;target=null;}
