function endFiveIntentDetails(intent,damage){let extra=intent.phase===1?` · Heal ${intent.healAmount}`:intent.phase===2?' · +1 Burn':intent.phase===3?` · Heal ${intent.healAmount}`:intent.phase===4?' · Chill attacks by 2':'';return `${damage} damage${intent.all?' to all':''}${extra} · Echo ${intent.phase}/5`;}
