 if(a.type==='sanctuary'){hit(a.value,user);state.sanctuary=Math.max(state.sanctuary||0,a.reduction||3);state.exhausted.add(a.name);state.log.push(`<b>Sanctuary</b> will reduce damage from the next enemy action by ${state.sanctuary}.`);}
